// ExactMove is generated by the organizer and retained server-side until confirmation.
type ExactMove struct {
	Source          string       `json:"source"`
	Target          string       `json:"target"`
	SourceRoot      string       `json:"-"`
	TargetRoot      string       `json:"-"`
	Snapshot        string       `json:"-"`
	CrossDevice     bool         `json:"crossDevice"`
	ContentSHA256   string       `json:"-"` // Full content evidence for compared regular files.
	Duplicate       bool         `json:"-"` // Read-only verification; source remains untouched.
	ValidateContext func() error `json:"-"` // Server-owned organizer guards, rechecked before each move.
}

// CheckPath rejects escapes and symlinks below an explicitly trusted base.
func CheckPath(base, path string) error {
	if !filepath.IsAbs(base) || !filepath.IsAbs(path) {
		return errors.New("路径必须是绝对路径")
	}
	rel, err := filepath.Rel(base, path)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return errors.New("路径超出允许范围")
	}
	p := filepath.Clean(base)
	parts := []string{"."}
	if rel != "." {
		parts = append(parts, strings.Split(rel, string(filepath.Separator))...)
	}
	for _, part := range parts {
		p = filepath.Join(p, part)
		fi, e := os.Lstat(p)
		if os.IsNotExist(e) {
			continue
		}
		if e != nil {
			return e
		}
		if fi.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("路径包含软链接：%s", p)
		}
	}
	return nil
}

// Snapshot records names, sizes, modes and modification times, with content hashes
// for small files. The traversal is bounded; unsupported trees remain in place.
func Snapshot(path string) (string, error) {
	h := sha256.New()
	count := 0
	err := filepath.WalkDir(path, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		count++
		if count > 5000 {
			return errors.New("工程超过 5000 个条目，保留原位，请缩小整理范围")
		}
		if d.Name() == ".git" || d.Name() == "node_modules" || d.Name() == ".venv" || d.Name() == "venv" {
			return errors.New("工程包含 Git 或依赖环境，保留原位")
		}
		if scan.IsSensitiveName(d.Name()) {
			return errors.New("包含疑似密钥或凭据，保留原位")
		}
		if d.Type()&os.ModeSymlink != 0 {
			return fmt.Errorf("包含软链接，保留工程原位：%s", d.Name())
		}
		fi, err := d.Info()
		if err != nil {
			return err
		}
		if !fi.IsDir() && !fi.Mode().IsRegular() {
			return errors.New("包含特殊文件，保留原位")
		}
		rel, _ := filepath.Rel(path, p)
		fmt.Fprintf(h, "%q\x00%d\x00%d\x00", rel, fi.Mode(), fi.ModTime().UnixNano())
		if !fi.IsDir() {
			fmt.Fprintf(h, "%d\x00", fi.Size())
			if fi.Size() <= 128*1024 {
				sum, e := put.FileSHA256(p)
				if e != nil {
					return e
				}
				fmt.Fprint(h, sum)
			}
		}
		return nil
	})
	return hex.EncodeToString(h.Sum(nil)), err
}

// Filesystems can round modification times differently when moving between volumes.
func crossSnapshot(path string) (string, error) {
	h := sha256.New()
	err := filepath.WalkDir(path, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(path, p)
		if err != nil {
			return err
		}
		if d.IsDir() {
			fmt.Fprintf(h, "d%q\x00", rel)
			return nil
		}
		if !d.Type().IsRegular() {
			return errors.New("包含特殊文件，无法核对跨磁盘搬迁")
		}
		sum, err := put.FileSHA256(p)
		if err != nil {
			return err
		}
		fmt.Fprintf(h, "f%q\x00%s\x00", rel, sum)
		return nil
	})
	return hex.EncodeToString(h.Sum(nil)), err
}

func IsCrossDevice(source, target string) bool {
	fi, err := os.Lstat(source)
	if err != nil {
		return false
	}
	a, b := deviceOf(fi), deviceOfPath(filepath.Dir(target))
	return a != 0 && b != 0 && a != b
}

// RenameNoReplace is shared with recoverable deletion; destinations never overwrite.
func RenameNoReplace(source, target string) error { return renameExclusive(source, target) }

// ApplyExact persists the entire undo intent BEFORE the first move, and never
// chooses a different destination from the preview the user confirmed.
func ApplyExact(cfg config.Config, moves []ExactMove) (*Summary, error) {
	return ApplyExactContext(context.Background(), cfg, moves)
}

// Cancellation stops between complete file operations, never halfway through a copy.
func ApplyExactContext(ctx context.Context, cfg config.Config, moves []ExactMove) (*Summary, error) {
	return ApplyExactContextWithUndoReady(ctx, cfg, moves, nil)
}

// ApplyExactContextWithUndoReady publishes the recovery receipt before moving files.
func ApplyExactContextWithUndoReady(ctx context.Context, cfg config.Config, moves []ExactMove, ready func(string) error) (*Summary, error) {
	if err := cfg.Validate(); err != nil {
		return nil, err
	}
	if len(moves) == 0 {
		return nil, errors.New("没有勾选可整理的文件")
	}
	if ctx.Err() != nil {
		return stoppedExact(cfg, moves), nil
	}
	if err := CheckPath(cfg.Root, filepath.Join(cfg.Root, cfg.Names.Control)); err != nil {
		return nil, err
	}
	lockDir := filepath.Join(cfg.Root, cfg.Names.Control)
	if err := os.MkdirAll(lockDir, 0755); err != nil {
		return nil, err
	}
	lock, err := os.OpenFile(filepath.Join(lockDir, "整理执行.lock"), os.O_CREATE|os.O_RDWR, 0600)
	if err != nil {
		return nil, err
	}
	defer lock.Close()
	if err = flock.Lock(lock); err != nil {
		return nil, err
	}
	defer flock.Unlock(lock)
	pending := map[string]string{}
	for _, m := range moves {
		if !m.Duplicate {
			pending[m.Target] = m.ContentSHA256
		}
	}
	if err := validateExactRelationships(moves); err != nil {
		return nil, err
	}
	for _, m := range moves {
		pendingDuplicate := m.Duplicate && m.ContentSHA256 != "" && pending[m.Target] == m.ContentSHA256
		if ctx.Err() != nil {
			return stoppedExact(cfg, moves), nil
		}
		if err := validateExactTarget(cfg, m, pendingDuplicate); err != nil {
			return nil, err
		}
	}
	now := time.Now().In(cfg.Location())
	s := &Summary{Root: cfg.Root, LogID: now.Format("20060102-150405.000000000")}
	u := undoLog{Version: 2, ID: s.LogID, CreatedAt: now.Format(time.RFC3339), Root: cfg.Root, Agent: "workshelf"}
	for _, m := range moves {
		if m.Duplicate {
			continue
		}
		var cross string
		if m.CrossDevice {
			cross, err = crossSnapshot(m.Source)
			if err != nil {
				return nil, fmt.Errorf("无法核对跨磁盘来源：%w", err)
			}
		}
		u.Entries = append(u.Entries, undoEntry{Mode: "move", From: m.Source, To: m.Target, Snapshot: m.Snapshot, CrossSnapshot: cross, SourceRoot: m.SourceRoot, TargetRoot: m.TargetRoot, SHA256: m.ContentSHA256, CrossDevice: m.CrossDevice})
	}
	// Even a permission/full-disk failure here must leave all sources untouched.
	if err := CheckPath(cfg.Root, undoDir(cfg)); err != nil {
		return nil, err
	}
	if err := os.MkdirAll(undoDir(cfg), 0700); err != nil {
		return nil, err
	}
	b, err := json.MarshalIndent(u, "", "  ")
	if err != nil {
		return nil, err
	}
	if len(u.Entries) > 0 {
		s.UndoPath, err = writeNewNumbered(filepath.Join(undoDir(cfg), "undo-organize-"+s.LogID+".json"), append(b, '\n'))
		if err != nil {
			return nil, fmt.Errorf("恢复清单写入失败，未移动文件：%w", err)
		}
		if ready != nil {
			if err := ready(s.UndoPath); err != nil {
				return nil, fmt.Errorf("保存恢复记录失败，未移动文件：%w", err)
			}
		}
	}
	for index, m := range moves {
		ri := ResultItem{Source: m.Source, Target: m.Target, CrossDevice: m.CrossDevice}
		if ctx.Err() != nil {
			remaining := stoppedExact(cfg, moves[index:])
			s.Stopped += remaining.Stopped
			s.Items = append(s.Items, remaining.Items...)
			break
		}
		err := validateExact(cfg, m)
		if err == nil && !m.Duplicate {
			err = os.MkdirAll(filepath.Dir(m.Target), 0755)
		}
		if err == nil && !m.Duplicate {
			if m.CrossDevice {
				err = moveCrossDevice(m.Source, m.Target)
			} else {
				err = renameExclusive(m.Source, m.Target)
			}
		}
		if err != nil {
			ri.Action = "失败"
			ri.Error = err.Error()
			s.Failed++
		} else if m.Duplicate {
			ri.Action = "重复保留"
			ri.KeptSource = true
			ri.SHA256 = m.ContentSHA256
			s.Skipped++
			s.Duplicates++
		} else {
			ri.Action = "搬走"
			ri.Undoable = true
			s.Moved++
		}
		s.Items = append(s.Items, ri)
	}
	// The durable undo path remains available even if this result receipt fails.
	if err := os.MkdirAll(logsDir(cfg), 0755); err == nil {
		b, _ := json.MarshalIndent(s, "", "  ")
		s.LogPath, _ = writeNewNumbered(filepath.Join(logsDir(cfg), "整理-"+s.LogID+".json"), append(b, '\n'))
	}
	return s, nil
}

func stoppedExact(cfg config.Config, moves []ExactMove) *Summary {
	s := &Summary{Root: cfg.Root, Stopped: len(moves)}
	for _, m := range moves {
		s.Items = append(s.Items, ResultItem{Source: m.Source, Target: m.Target, CrossDevice: m.CrossDevice, Action: "未开始", KeptSource: true})
	}
	return s
}

func withinExact(p, base string) bool {
	rel, e := filepath.Rel(base, p)
	return e == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}

// Directory merges produce many leaf moves. Check path ancestry in O(n*depth)
// rather than comparing every pair of files before the first operation.
func validateExactRelationships(moves []ExactMove) error {
	sources, targets := map[string]bool{}, map[string]bool{}
	conflict := func() error { return errors.New("整理项存在重复或嵌套，需重新预览") }
	for _, m := range moves {
		source, target := filepath.Clean(m.Source), filepath.Clean(m.Target)
		if sources[source] || (!m.Duplicate && targets[target]) {
			return conflict()
		}
		sources[source] = true
		if !m.Duplicate {
			targets[target] = true
		}
	}
	hasSourceAncestor := func(path string) bool {
		for {
			if sources[path] {
				return true
			}
			parent := filepath.Dir(path)
			if parent == path {
				return false
			}
			path = parent
		}
	}
	for _, m := range moves {
		if hasSourceAncestor(filepath.Dir(filepath.Clean(m.Source))) || hasSourceAncestor(filepath.Clean(m.Target)) {
			return conflict()
		}
	}
	return nil
}

func validateExact(cfg config.Config, m ExactMove) error {
	return validateExactTarget(cfg, m, false)
}

func validateExactTarget(cfg config.Config, m ExactMove, pendingDuplicate bool) error {
	if m.ValidateContext != nil {
		if err := m.ValidateContext(); err != nil {
			return err
		}
	}
	if m.Snapshot == "" {
		return errors.New("缺少源文件快照，需重新预览")
	}
	if err := CheckPath(m.SourceRoot, m.Source); err != nil {
		return err
	}
	targetRoot := m.TargetRoot
	if targetRoot == "" {
		targetRoot = cfg.Root
	}
	if err := CheckPath(targetRoot, m.Target); err != nil {
		return err
	}
	if m.Target == cfg.Root || withinExact(m.Target, filepath.Join(cfg.Root, cfg.Names.Control)) || m.Source == cfg.Root || withinExact(m.Source, filepath.Join(cfg.Root, cfg.Names.Control)) || withinExact(m.Target, m.Source) {
		return errors.New("不能整理总控、总目录或将目录移入自身")
	}
	if m.Duplicate {
		if m.ContentSHA256 == "" {
			return errors.New("缺少完整重复证据，请重新预览")
		}
		if !pendingDuplicate {
			fi, err := os.Lstat(m.Target)
			if err != nil || !fi.Mode().IsRegular() {
				return fmt.Errorf("保留文件未成功归档或已变化，重复来源保持原处：%s", m.Target)
			}
			sum, err := put.FileSHA256(m.Target)
			if err != nil || sum != m.ContentSHA256 {
				return fmt.Errorf("保留文件内容已变化，重复来源保持原处：%s", m.Target)
			}
		}
	} else if _, err := os.Lstat(m.Target); !os.IsNotExist(err) {
		return fmt.Errorf("目标已变化或被占用，需重新预览：%s", m.Target)
	}
	got, err := Snapshot(m.Source)
	if err != nil {
		return err
	}
	if got != m.Snapshot {
		return fmt.Errorf("源文件在预览后已变化，需重新预览：%s", m.Source)
	}
	if m.ContentSHA256 != "" {
		fi, err := os.Lstat(m.Source)
		if err != nil || !fi.Mode().IsRegular() {
			return errors.New("参与内容核对的来源已变化，请重新预览")
		}
		sum, err := put.FileSHA256(m.Source)
		if err != nil || sum != m.ContentSHA256 {
			return fmt.Errorf("来源内容在预览后已变化，请重新预览：%s", m.Source)
		}
	}
	if IsCrossDevice(m.Source, m.Target) != m.CrossDevice {
		return errors.New("磁盘位置已变化，需重新预览")
	}
	return nil
}

func copyExact(src, dst string) error {
	fi, err := os.Lstat(src)
	if err != nil {
		return err
	}
	if !fi.IsDir() {
		if !fi.Mode().IsRegular() {
			return errors.New("不是普通文件")
		}
		if _, err := copyFileVerified(src, dst, fi); err != nil {
			return err
		}
		return os.Chmod(dst, fi.Mode().Perm())
	}
	if err := os.Mkdir(dst, fi.Mode().Perm()); err != nil {
		return err
	}
	var dirs []string
	err = filepath.WalkDir(src, func(p string, d fs.DirEntry, e error) error {
		if e != nil {
			return e
		}
		if d.Type()&os.ModeSymlink != 0 {
			return errors.New("复制过程中出现软链接")
		}
		rel, _ := filepath.Rel(src, p)
		target := filepath.Join(dst, rel)
		if d.IsDir() {
			dirs = append(dirs, p)
			if rel != "." {
				return os.Mkdir(target, 0755)
			}
			return nil
		}
		return copyExact(p, target)
	})
	if err != nil {
		return err
	}
	for i := len(dirs) - 1; i >= 0; i-- {
		p := dirs[i]
		fi, err := os.Stat(p)
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(src, p)
		to := filepath.Join(dst, rel)
		if err := os.Chmod(to, fi.Mode().Perm()); err != nil {
			return err
		}
		if err := os.Chtimes(to, fi.ModTime(), fi.ModTime()); err != nil {
			return err
		}
	}
	return nil
}
